public final MatchResult match(CharSequence uri) {
    // Check for null inputs
    if (uri == null) {
        return null;
    }

    // Create a matcher from the pattern and the input URI
    Matcher matcher = pattern.matcher(uri);

    // Check if the match is successful
    if (matcher.matches()) {
        // If the match is successful, create a new MatchResult object
        // with the variables in the template and their corresponding values
        // in the input URI
        Map<String, String> variables = new HashMap<>();
        int groupCount = matcher.groupCount();
        for (int i = 0; i < groupCount; i++) {
            String groupName = matcher.getGroup(i + 1);
            if (groupName != null) {
                variables.put(groupName, matcher.group(groupName));
            }
        }

        return new MatchResult(variables);
    }

    // If the match is not successful, return null
    return null;
}

