}

@Override
public Action inspect(AtmosphereResource r) {
    // Check if the transport is not supported
    if (!AtmosphereResource.TRANSPORT.isSupported(r.getTransport())) {
        return Action.CONTINUE;
    }

    // Check if the connection is still open
    if (!r.isOpen()) {
        return Action.CONTINUE;
    }

    // Check if the resource is not marked as destroyed
    if (r.isDestroyed()) {
        return Action.CONTINUE;
    }

    // Check if the resource is suspended
    if (r.isSuspended()) {
        return Action.CONTINUE;
    }

    // Suspend the resource
    try {
        r.suspend();
    } catch (IOException e) {
        logger.error("Failed to suspend the resource: {}", r, e);
    }

    return Action.CONTINUE;
}

