    // Create a list to store the vertices and edges of the tour
    List<V> vertices = new ArrayList<>();
    List<E> edges = new ArrayList<>();

    // Iterate over the edges in the tour set
    for (E edge : tour) {
        // Get the incident vertices of the edge
        V v1 = graph.getEdgeSource(edge);
        V v2 = graph.getEdgeTarget(edge);

        // Add the vertices and edges to the lists
        vertices.add(v1);
        vertices.add(v2);
        edges.add(edge);
    }

    // Create the path
    return new GraphPath(vertices, edges, graph);
}

