public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    FileInputStream fin = new FileInputStream(file);
    BufferedReader br = new BufferedReader(new InputStreamReader(fin));
    String line;
    while ((line = br.readLine()) != null) {
        if (line.startsWith("Snapshot")) {
            String[] tokens = line.split(",");
            long timestamp = Long.parseLong(tokens[2]);
            String[] timeRange = timeRanges.get(timeRanges.size() - 1).getTimeRange();
            if (timestamp >= Long.parseLong(timeRange[0]) && timestamp <= Long.parseLong(timeRange[1])) {
                String threadSnapshotJson = br.readLine();
                ThreadSnapshot threadSnapshot = JSONUtil.parse(threadSnapshotJson, ThreadSnapshot.class);
                threadSnapshots.add(threadSnapshot);
            }
        }
    }
    br.close();
    return threadSnapshots;
}

/**
* parse thread snapshots from a file and filter them according to the specified time range
* 
* @param file the file to parse
