            return timeStamp >= timeRange.getStartTime() && timeStamp <= timeRange.getEndTime();
          }
          return false;
        })
        .collect(Collectors.toList());
    linesByTimeRange.add(filteredLines);
  }

// step 2: parse the filtered lines to ThreadSnapshot objects and add them to the list
 List<ThreadSnapshot> snapshots = new ArrayList<>();
 for (List<String> lines : linesByTimeRange) {
