public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (RandomAccessFile randomAccessFile = new RandomAccessFile(file, "r")) {
        for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
            long startTime = timeRange.getStart();
            long endTime = timeRange.getEnd();
            long currentPosition = 0;
            while (currentPosition < file.length()) {
                long startTimestamp = randomAccessFile.readLong();
                if (startTimestamp >= endTime) {
                    break;
                }
                long d = randomAccessFile.readLong();
                long threadId = randomAccessFile.readInt();
                String threadName = randomAccessFile.readUTF();
                long threadStatus = randomAccessFile.readInt();
                List<StackTraceElement> stackTrace = new ArrayList<>();
                while (randomAccessFile.readInt() == 0) {
                    int frameId = randomAccessFile.readInt();
                    String declaringClass = randomAccessFile.readUTF();
                    String methodName = randomAccessFile.readUTF();
                    String fileName = readExtra(randomAccessFile, file);
                    int lineNumber = randomAccessFile.readInt();
                    stackTrace.add(new StackTraceElement(declaringClass, methodName, fileName, lineNumber));
                }
                if (startTimestamp >= startTime && startTimestamp < endTime) {
                    threadSnapshots.add(new ThreadSnapshot(threadId, threadName, threadStatus, stackTrace));
                }
                currentPosition = randomAccessFile.getFilePointer();
            }
        }
        return threadSnapshots;
    }
